void input_to_data(int fd, void *vdata) {
    struct bench_args_t *data = (struct bench_args_t *)vdata;
    char *p, *s;
    // Zero-out everything.
    memset(vdata, 0, sizeof(struct bench_args_t));
    // Load input string
    p = readfile(fd);

    s = find_section_start(p, 1);
    parse_int32_t_array(s, data->a, SIZE);
    free(p);
}

void data_to_input(int fd, void *vdata) {
    struct bench_args_t *data = (struct bench_args_t *)vdata;

    write_section_header(fd);
    write_int32_t_array(fd, data->a, SIZE);
}

/* Output format:
%% Section 1
TYPE[SIZE]: the array
*/

void output_to_data(int fd, void *vdata) {
    struct bench_args_t *data = (struct bench_args_t *)vdata;
    char *p, *s;
    // Zero-out everything.
    memset(vdata, 0, sizeof(struct bench_args_t));
    // Load input string
    p = readfile(fd);

    s = find_section_start(p, 1);
    parse_int32_t_array(s, data->a, SIZE);
    free(p);
}

void data_to_output(int fd, void *vdata) {
    struct bench_args_t *data = (struct bench_args_t *)vdata;

    write_section_header(fd);
    write_int32_t_array(fd, data->a, SIZE);
}

int check_data(void *vdata, void *vref) {
    struct bench_args_t *data = (struct bench_args_t *)vdata;
    struct bench_args_t *ref = (struct bench_args_t *)vref;
    int has_errors = 0;
    int i;
    TYPE data_sum, ref_sum;

    // Check sortedness and sum
    data_sum = data->a[0];
    ref_sum = ref->a[0];
    for (i = 1; i < SIZE; i++) {
        has_errors |= data->a[i - 1] > data->a[i];
        data_sum += data->a[i];
        ref_sum += ref->a[i];
    }
    has_errors |= (data_sum != ref_sum);

    for (i = 0; i < SIZE; i++) {
        if (data->a[i] != ref->a[i]) {
            printf(
                "ERROR: data->a[%d] = %" PRId32 ", ref->a[%d] = %" PRId32 "\n",
                i,
                data->a[i],
                i,
                ref->a[i]);
        }
    }
    if ((data_sum != ref_sum)) {
        printf("Ref sum: %" PRId32 "\n", ref_sum);
        printf("Data sum: %" PRId32 "\n", data_sum);
    }

    // Return true if it's correct.
    return !has_errors;
}

int main() {
    char *in_file;
    char *check_file;

    in_file = "input.data";
    check_file = "check.data";

    int in_fd;
    char *data;
    data = (char *)malloc(INPUT_SIZE);
    assert(data != NULL && "Out of memory");
    in_fd = open(in_file, O_RDONLY);
    assert(in_fd > 0 && "Couldn't open input data file");
